<div class="admin-title"><div><span class="eyebrow">ONE PLACE. EVERY DETAIL.</span><h1><?= t($group==='appearance'?'Design your atmosphere':'Site settings') ?></h1><p><?= t('The same field schema drives validation, defaults and this settings screen.') ?></p></div><a class="btn secondary" href="<?= e(url()) ?>" target="_blank" rel="noopener"><?= icon('eye') ?><?= t('Preview site') ?></a></div><nav class="admin-tabs"><?php foreach ($groups as $key): ?><a href="<?= e(au('settings',['group'=>$key])) ?>" class="<?= $key===$group?'active':'' ?>"><?= t($key) ?></a><?php endforeach ?></nav>
<?php if (in_array($group,['epay','codepay'],true)): ?><div class="alert warning"><?= t('Payment adapters are disabled by default. PHP 7.4 through 8.5 use the same payment implementation. Live payments require HTTPS, your own merchant account, an exact compatible protocol and a successful real callback test. Never paste keys into public content.') ?><?php if ($group==='codepay'): ?><p><?= t('Legacy CodePay service availability is not verified. Floating-amount payment mode is intentionally rejected; use exact signed amounts only.') ?></p><?php endif ?><p><?= t('Notify URL') ?>: <code><?= e($a->config['url'].'/notify.php?gateway='.$group) ?></code></p></div><?php endif ?>
<?php if ($group==='appearance'): ?><section class="panel section"><div class="section-heading"><h2><?= t('Five ways to feel at home') ?></h2><span class="pill soft"><?= t('Live preview') ?></span></div><div class="theme-preview-grid"><?php foreach (['tide'=>'Quiet, light and fluid','dusk'=>'Soft, layered and dreamlike','paper'=>'Warm, editorial and unhurried','graphite'=>'Precise, minimal and focused','citrus'=>'Bright, friendly and energetic'] as $theme=>$description): ?><button class="theme-preview <?= $s->get('theme')===$theme?'active':'' ?>" data-preview="<?= e($theme) ?>"><div class="mini-site"><div class="mini-hero"></div><div class="mini-cards"><i></i><i></i><i></i></div></div><strong><?= t($theme) ?></strong><small><?= t($description) ?></small></button><?php endforeach ?></div></section><?php endif ?>
<?= form_start('admin_settings') . hidden('group',$group) ?><section class="panel"><div class="settings-toolbar"><div><h2><?= t($group) ?></h2><p class="hint"><?= t('Changes apply after saving. Visitors may retain their own appearance preference until they reset it.') ?></p></div><input class="input settings-search" type="search" data-setting-search placeholder="<?= t('Filter these settings') ?>" aria-label="<?= t('Filter these settings') ?>"></div><div class="settings-grid"><?php foreach ($s->schema() as $key=>$definition): if ($definition[0]!==$group) {continue;} [$g,$label,$type,$default]=$definition;$value=$s->get($key); ?><div class="setting-field <?= $type==='textarea'?'wide':'' ?>" data-setting-row="<?= e($key.' '.tr($label)) ?>"><?php if ($type==='bool'): ?><label class="toggle-row"><span><strong><?= t($label) ?></strong><small><?= e($key) ?></small></span><span class="toggle"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= $value?'checked':'' ?>><span></span></span></label><?php elseif ($type==='select'): select_field($key,$label,options($definition[4]),$value,['data-live-setting'=>$key]); elseif ($type==='secret'): field($key,$label,'',preg_match('/_(private|public)$/D',$key)?'textarea':'password',['autocomplete'=>'new-password','placeholder'=>tr($value!==''?'Configured; leave blank to keep':'Not configured')]); check_field('clear_'.$key,'Clear stored secret',false); elseif ($type==='int'): field($key,$label,$value,'number',['min'=>(string)$definition[5],'max'=>(string)$definition[6],'data-live-setting'=>$key]); elseif ($type==='textarea'): field($key,$label,$value,'textarea'); else: field($key,$label,$value,'text',['data-live-setting'=>$key]); endif ?><?php if ($type!=='bool'): ?><small class="setting-key"><?= e($key) ?></small><?php endif ?></div><?php endforeach ?></div><div class="save-bar"><span class="hint"><?= icon('shield') ?><?= t('Permission checked. Changes are audited.') ?></span><?php button('Save settings','','check'); ?></div></section></form>
<?php if ($group==='email'): ?><section class="panel section"><?= form_start('admin_mail_test') ?><p><?= t('Send a test message to the currently signed-in administrator. No other recipient can be supplied here.') ?></p><?php button('Test SMTP delivery','secondary','message'); ?></form></section><?php endif ?>
